\begin{align*}
A_{1} &= \sum_{u = 0}^{\infty} 2^{-u(3 + u)}\sum_{v = 0}^{\infty} 2^{-v(1 + v)} \\
&= \sum_{u = 0}^\infty 2^{-u(3 + u)}\left(1 + 4^{-\frac{1}{2}} + 4^{-2} + 4^{-\frac{5}{2}} + \dotsb\right) \\
