\left(\frac{1}{4}\right)^{2x+8} &= (16)^{2x+5}\\
\implies 2x+8 & = \frac{2\ln (16)}{\ln 4}\\
\implies 2x+8 & = 4\\
\implies 2x & = -4\\
\implies x & = -2
\end{align*}

